def _trace(self, target, spec, scope):
    if not self.recursive:
        scope[glom] = scope[Inspect]
    if self.echo:
        print('---')
        print('path:  ', scope[Path] + [spec])
        print('target:', target)
    if self.breakpoint:
        self.breakpoint()
    try:
        ret = scope[Inspect](target, spec, scope)
    except Exception:
        if self.post_mortem:
            self.post_mortem()
        raise
    if self.echo:
        print('output:', ret)
        print('---')
    return ret
